 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    # The horizontal colored strip is the launch line. Marker 2 builds a
    # four-cell column; marker 8 builds a three-cell column, with color 1
    # between the marker cap and the strip.
    base = next((r for r, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if base is None:
        return out
    for c, v in enumerate(grid[base]):
        if v in (2, 8):
            height = 4 if v == 2 else 3
            top = max(0, base - height)
            out[top][c] = v
            for r in range(top + 1, base):
                out[r][c] = 1
    return out
